"""Rendering constants shared by generated files."""
from __future__ import annotations

from typing import Final

FORMAT_VERSION: Final = "6"
HEADER: Final = "# Generated by kg-build-system. Do not edit manually."

FILE_DIRECTIVES: Final = (
    "# fmt: off",
    "# isort: skip_file",
    "# ruff: noqa: F401",
    "# pyright: reportUnusedImport=false",
    "# pyright: reportUnknownVariableType=false",
)

REPRESENTATIVE_TYPES: Final = {
    "date": "Date",
    "time": "Time",
    "timestamp": "Timestamp",
    "uuid": "Uuid",
}

REPRESENTATIVE_IMPORT: Final = (
    f"from kg_build_system import Array, {', '.join(sorted(set(REPRESENTATIVE_TYPES.values())))}"
)


__all__ = [
    "FILE_DIRECTIVES", "FORMAT_VERSION", "HEADER", "REPRESENTATIVE_IMPORT",
    "REPRESENTATIVE_TYPES",
]
